# owner: platform
"""Contact sheet rows for substitute teachers."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students):
    if not students:
        raise ProjectError("no students given")
    for item in students:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )


def _cells(students):
    ordered = sorted(
        students, key=lambda item: item.display_name
    )
    return [
        (item.display_name, item.section, item.email)
        for item in ordered
    ]


def _line(entry, widths):
    pairs = zip(entry, widths)
    text = "  ".join(
        cell.ljust(wide) for cell, wide in pairs
    )
    return text.rstrip()


# ---
def contact_rows(students: list[Student]) -> list[str]:
    """Name, section and email rows, sorted by name."""
    _check(students)
    cells = _cells(students)
    widths = [
        max(len(cell) for cell in column)
        for column in zip(*cells)
    ]
    return [_line(entry, widths) for entry in cells]
