# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def _make(last, first, section, email):
    return Student("id", last, first, section, email)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _make("Zed", "Al", "B", "z@x.org"),
            _make("Abe", "Bo", "AA", "a@x.org")
        ])
        self.assertEqual(rows, [
            "Abe, Bo  AA  a@x.org",
            "Zed, Al  B   z@x.org"
        ])

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as ctx:
            contact_rows([_make("Abe", "Bo", "A", None)])
        self.assertIn("Abe, Bo", str(ctx.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
